"""Final ERD (v4) — generated from the Drizzle snapshot (drizzle/full/meta/0000_snapshot.json), so it cannot drift
from schema/*.ts. Better Auth tables that the CLI generates but our placeholder does not declare are added below with
INDICATIVE columns (verify against the real CLI output).
Usage: python3 erd_v4.py <snapshot.json> <out_dir>
"""
import json, sys, subprocess, html, pathlib

snap = json.load(open(sys.argv[1]))
out = pathlib.Path(sys.argv[2]); out.mkdir(parents=True, exist_ok=True)
enums = {v["name"] for v in snap["enums"].values()}

GROUPS = {
    "Better Auth (generated by its CLI — not designed here)": ["user", "session", "account", "verification", "organization", "member", "invitation"],
    "Identity extension (decision 3)": ["org_profiles", "supplier_profiles", "buyer_locations"],
    "Catalogue (decision 10)": ["categories", "category_attributes", "products", "product_images", "csv_imports"],
    "Cart & orders (decision 11)": ["carts", "cart_items", "orders", "sub_orders", "order_lines", "sub_order_events", "proforma_invoices", "order_payments"],
    "Finance & platform (decisions 9, 11)": ["ledger_entries", "settings", "audit_log", "invoice_counters"],
    "Stretch — separate migrations after G3": ["price_tiers", "buyer_prices", "rfq_requests", "rfq_invitations", "rfq_quotes", "payments", "payment_events"],
}
GROUP_STYLE = {  # (cluster fill, header colour)
    "Better Auth": ("#F3F4F6", "#6B7280"), "Identity": ("#F4F7FC", "#2B579A"), "Catalogue": ("#F2F8F6", "#0F766E"),
    "Cart": ("#FBF8F3", "#2B579A"), "Finance": ("#F6F4FB", "#5B3FA0"), "Stretch": ("#FFF8EC", "#B7791F"),
}
def style(group): return next(v for k, v in GROUP_STYLE.items() if group.startswith(k))

tables = {}
for t in snap["tables"].values():
    name = t["name"]
    cols = []
    for c in t["columns"].values():
        typ = c["type"].replace("timestamp with time zone", "timestamptz")
        if typ.startswith('"public".') or typ in enums: typ = "enum " + typ.split(".")[-1].strip('"')
        cols.append({"name": c["name"], "type": typ, "pk": c.get("primaryKey", False), "null": not c.get("notNull", False),
                     "uq": c.get("isUnique", False)})
    pk_comp = [pk["columns"] for pk in t["compositePrimaryKeys"].values()]
    for cols_ in pk_comp:
        for c in cols: c["pk"] = c["pk"] or c["name"] in cols_
    notes = []
    for i in t["indexes"].values():
        if not i["isUnique"]: continue
        names = [x["expression"] for x in i["columns"]]
        if len(names) == 1 and not i.get("where"):
            for c in cols:
                if c["name"] == names[0]: c["uq"] = True
        else:
            notes.append("UQ (" + ", ".join(names) + ")" + (" WHERE …" if i.get("where") else ""))
    fks = [(f["columnsFrom"][0], f["tableTo"]) for f in t["foreignKeys"].values()]
    for c in cols: c["fk"] = any(c["name"] == fc for fc, _ in fks)
    tables[name] = {"cols": cols, "fks": fks, "notes": notes, "checks": len(t["checkConstraints"])}

# Better Auth tables not declared by the placeholder — indicative columns (verify in the generated schema).
def ba(cols, fks=()):
    return {"cols": [{"name": n, "type": ty, "pk": n == "id", "null": nl, "uq": uq, "fk": n in dict(fks)} for n, ty, nl, uq in cols],
            "fks": list(fks), "notes": ["indicative — verify CLI output"], "checks": 0}
tables.setdefault("session", ba([("id", "text", False, False), ("user_id", "text", False, False), ("token", "text", False, True),
    ("expires_at", "timestamptz", False, False), ("active_organization_id", "text", True, False), ("ip_address", "text", True, False),
    ("user_agent", "text", True, False)], [("user_id", "user")]))
tables.setdefault("account", ba([("id", "text", False, False), ("user_id", "text", False, False), ("account_id", "text", False, False),
    ("provider_id", "text", False, False), ("password", "text", True, False)], [("user_id", "user")]))
tables.setdefault("verification", ba([("id", "text", False, False), ("identifier", "text", False, False), ("value", "text", False, False),
    ("expires_at", "timestamptz", False, False)]))
tables.setdefault("invitation", ba([("id", "text", False, False), ("organization_id", "text", False, False), ("email", "text", False, False),
    ("role", "text", False, False), ("status", "text", False, False), ("inviter_id", "text", False, False), ("expires_at", "timestamptz", False, False)],
    [("organization_id", "organization"), ("inviter_id", "user")]))
for n in ("user", "organization", "member"):
    tables[n]["notes"] = ["placeholder columns — CLI output is authoritative"]

listed = {t for g in GROUPS.values() for t in g}
assert listed == set(tables), (listed ^ set(tables))

HUBS = {"organization", "user"}
ACTOR_COLS = {"created_by_user_id", "added_by_user_id", "placed_by_user_id", "cancelled_by_user_id", "recorded_by_user_id",
              "updated_by_user_id", "actor_user_id", "status_changed_by", "inviter_id"}

def node(name, group):
    _, head = style(group)
    t = tables[name]
    rows = [f'<TR><TD COLSPAN="3" BGCOLOR="{head}" ALIGN="LEFT"><FONT COLOR="white"><B>{name}</B></FONT></TD></TR>']
    for c in t["cols"]:
        key = " ".join(k for k, f in (("PK", c["pk"]), ("FK", c["fk"]), ("UQ", c["uq"])) if f)
        colour = "#B03A2E" if c["pk"] else "#1F6F43" if c["fk"] else "#5B3FA0" if c["uq"] else "#999999"
        typ = html.escape(c["type"]) + ("?" if c["null"] else "")
        hub = next((tt for fc, tt in t["fks"] if fc == c["name"] and tt in HUBS and name not in HUBS), None)
        if hub: typ += f' <FONT COLOR="#1F6F43">→ {hub}</FONT>'
        money = ' BGCOLOR="#FFF7E0"' if c["name"].endswith("_cents") else ""
        rows.append(f'<TR><TD ALIGN="LEFT"><FONT COLOR="{colour}" POINT-SIZE="9">{key or "&#160;"}</FONT></TD>'
                    f'<TD ALIGN="LEFT" PORT="{c["name"]}"{money}>{c["name"]}</TD>'
                    f'<TD ALIGN="LEFT"><FONT COLOR="#666666">{typ}</FONT></TD></TR>')
    for n in t["notes"]:
        rows.append(f'<TR><TD COLSPAN="3" ALIGN="LEFT" BGCOLOR="#F2F2F2"><FONT POINT-SIZE="9" COLOR="#555555"><I>{html.escape(n)}</I></FONT></TD></TR>')
    if t["checks"]:
        rows.append(f'<TR><TD COLSPAN="3" ALIGN="LEFT" BGCOLOR="#F2F2F2"><FONT POINT-SIZE="9" COLOR="#555555"><I>{t["checks"]} CHECK constraint(s) · RLS on</I></FONT></TD></TR>')
    return f'"{name}" [label=<<TABLE BORDER="1" COLOR="{head}" CELLBORDER="0" CELLSPACING="0" CELLPADDING="3">{"".join(rows)}</TABLE>>];'

lines = ['digraph ERD {',
         'graph [fontname="Inter" rankdir=TB splines=true nodesep=0.4 ranksep=0.9 pad=0.5 bgcolor=white newrank=true',
         f'       label=<<B>HoReCa B2B Marketplace — complete database ({len(tables)} tables)</B><BR/>'
         '<FONT POINT-SIZE="12" COLOR="#555555">Generated from the Drizzle schema of horeca-decisions-9-11. '
         'PK red · FK green · UQ purple · ? = nullable · money columns (bigint cents) highlighted · '
         '“→ organization” / “→ user” = foreign key to that Better Auth table (not drawn as a line)</FONT>> labelloc=t labeljust=l fontsize=22];',
         'node [shape=plaintext fontname="Inter" fontsize=10];', 'edge [color="#555555" arrowhead=crow arrowtail=none dir=both penwidth=0.9];']
for gi, (group, names) in enumerate(GROUPS.items()):
    fill, head = style(group)
    lines.append(f'subgraph cluster_{gi} {{ label=<<B>{html.escape(group)}</B>> fontsize=14 fontcolor="{head}" style="rounded,filled" '
                 f'fillcolor="{fill}" color="{head}" margin=18;')
    lines += [node(n, group) for n in names]
    lines.append('}')
for name, t in tables.items():
    for col, target in t["fks"]:
        if target in HUBS and name not in HUBS:
            continue  # shown as "→ organization" / "→ user" inside the column (keeps the picture readable)
        lines.append(f'"{target}" -> "{name}":"{col}" [arrowtail=tee];')
lines.append('}')
dot = out / "erd-complete.dot"; dot.write_text("\n".join(lines))
for fmt in ("png", "svg", "pdf"):
    args = ["dot", f"-T{fmt}", str(dot), "-o", str(out / f"erd-complete.{fmt}")] + (["-Gdpi=110"] if fmt == "png" else [])
    subprocess.run(args, check=True)
fk_total = sum(len(t["fks"]) for t in tables.values())
print(f"ERD: {len(tables)} tables, {fk_total} foreign keys")
